# DOS U preset: Monkey Island 2 (mi2kor Korean patch), 2 bpp anti-aliased.
# M2U*.SVF baked by tools/korean/scumm-fonts/m2u.tsv: dialogue, verbs and the
# sentence line in a gothic face, the title/credit card in a serif face.
# Cells per charset: cs0/cs6 22x24, cs1/cs3/cs5 16x16, cs2 18x18, cs4 26x24, cs7 24x24, cs8 16x16 (own file).
# Charsets that share a cell share one SVF. Licences: see M12FONT.TXT beside this file.
# MI2 draws its verb line in charset 6, which has no korean06.fnt: it uses the charset 0 file.
[hires]
scale=2
alpha=true
missing=u+25a1

[encoding]
codepage=cp949

[font.0]
bitmap=M2U0.SVF

[font.1]
bitmap=M2U1.SVF

[font.2]
bitmap=M2U2.SVF

[font.3]
bitmap=M2U1.SVF

[font.4]
bitmap=M2U4.SVF

[font.5]
bitmap=M2U1.SVF

[font.6]
bitmap=M2U0.SVF

[font.7]
bitmap=M2U7.SVF

[font.8]
bitmap=M2U8.SVF

[latin]
mode=proportional
metrics=font
# No Latin companion here: font=same is a no-op today, and just says so -
# ASCII stays on each charset's own SVF, never the game's internal font.
font=same
# The card fonts (charsets 4, 7, 8) are trimmed: '.' and ',' carry a game offsY of 9 in a
# 15 px cell. The baked SVF already sets the baseline, so drop the game's offsets.
baseline=face

# MI2's own pictogram: the skull-and-crossbones dialogue bullet at 0x07 (always the
# first byte of a spoken line in korean.trs; no Latin face has anything for it).
# Everything else the patch parked on an odd byte code is real punctuation and is
# drawn by the replacement font like any other character:
#   0x5e ellipsis (every occurrence in korean.trs trails a clause: "..." / trailing off)
#   0x5c exclamation mark (korean.trs: "원해!  모든 퍼즐!  온갖 생고생!")
#   0x60 double quote, both opening and closing (one byte serves both roles in the text,
#     so there is no separate open/close code to distinguish)
[glyphs]
0x07 = keep
0x5e = u+2026
0x5c = u+0021
0x60 = u+0022
